function Instagram({size=18}:{size?:number}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/></svg>}
function Facebook({size=18}:{size?:number}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M14 21v-8h3l.5-3H14V8.5c0-.9.3-1.5 1.6-1.5H18V4h-2.7C12.1 4 10 5.6 10 8.6V10H7v3h3v8z"/></svg>}
type View="ai"|"materials"|"production"|"script"|"backgrounds"|"flow"|"studio"|"library"|"avatars"|"channels"|"settings"|"publish";
type Row=Record<string,any>;
const platformInfo:Record<Platform,{name:string;icon:React.ComponentType<{size?:number}>;short:string;color:string}>={facebook:{name:"Facebook",icon:Facebook,short:"Reels",color:"#1877f2"},instagram:{name:"Instagram",icon:Instagram,short:"Reels",color:"#ce4674"},tiktok:{name:"TikTok",icon:Music2,short:"Видео",color:"#161b24"},telegram:{name:"Telegram",icon:Send,short:"Канал",color:"#269dd3"}};
const statusNames:Record<string,string>={submitting:"Отправляется",pending:"В очереди",processing:"Обрабатывается",completed:"Видео готово",failed:"Ошибка",unconfirmed:"Проверьте в сервисе",uploading:"Загрузка видео",creating:"Создание публикации",draft:"Черновик",publishing:"Отправляется",published:"Опубликовано",scheduled:"Запланировано",partial:"Частично опубликовано",needs_attention:"Требует проверки",awaiting_approval:"Ожидает одобрения"};
const navItems:{id:View;title:string;icon:typeof Clapperboard}[]=[{id:"script",title:"Генератор сценария",icon:Sparkles},{id:"studio",title:"Студия",icon:Clapperboard},{id:"production",title:"Сцены и монтаж",icon:Film},{id:"materials",title:"AI-материалы",icon:ImagePlus},{id:"ai",title:"AI-подключения",icon:SlidersHorizontal},{id:"backgrounds",title:"Фоны и локации",icon:ImagePlus},{id:"flow",title:"Видео · Google Flow",icon:Film},{id:"library",title:"Мои выпуски",icon:FolderOpen},{id:"avatars",title:"Мои аватары",icon:Users},{id:"channels",title:"Каналы публикации",icon:Radio}];
function parse(v:any){if(typeof v!=="string")return v||{};try{return JSON.parse(v)}catch{return {}}}
function connectorData(r:any){if(r.status!=="success")throw new Error(r.message||"Подключение недоступно.");if(r.result.structuredContent!==undefined)return r.result.structuredContent;for(const c of r.result.content||[])if(c.type==="text"){try{return JSON.parse(c.text)}catch{}}throw new Error("Сервис не вернул данные.")}
function Modal({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();const el=ref.current;return()=>el?.close()},[]);return <dialog ref={ref} className="modal" onCancel={onClose} onClose={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose()}} aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" aria-label="Закрыть" onClick={onClose}><X size={20}/></button></div>{children}</dialog>}
function PlatformIcon({platform,size=18}:{platform:Platform;size?:number}){const Icon=platformInfo[platform].icon;return <span className={`social-icon ${platform}`}><Icon size={size}/></span>}
function Empty({icon:Icon,title,children}:{icon:typeof Film;title:string;children:React.ReactNode}){return <div className="empty-state"><div className="empty-icon"><Icon size={28}/></div><h3>{title}</h3>{children}</div>}

