  const newProject=async()=>{if(dirty&&!await save())return;setProject(blankProject());setSavedAt(null);setDirty(false);setSelected([]);setReviewed(false);setMetadata(null);renderKey.current=crypto.randomUUID();publishKey.current=crypto.randomUUID();go("script")};
